/* @autogenerated */
package net.civeira.phylax.feature.oauth.profile.infrastructure.driver.html;

import java.net.URI;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.Optional;
import java.util.Set;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.infrastructure.CurrentRequest;
import net.civeira.phylax.feature.oauth.client.domain.ClientDetails;
import net.civeira.phylax.feature.oauth.client.domain.gateway.ClientStoreGateway;
import net.civeira.phylax.feature.oauth.session.domain.SessionInfo;
import net.civeira.phylax.feature.oauth.session.domain.gateway.SessionStoreGateway;

/** The way back from the profile leads only to an application of the session, with its issuer. */
class ProfileBackLinkUnitTest {
  private static final String ISSUER = "https://idp.example/oauth/openid/acme";

  private SessionStoreGateway sessions;
  private ClientStoreGateway clients;
  private ProfileBackLink backLink;

  @BeforeEach
  void setUp() {
    sessions = Mockito.mock(SessionStoreGateway.class);
    clients = Mockito.mock(ClientStoreGateway.class);
    CurrentRequest current = Mockito.mock(CurrentRequest.class);
    Mockito.when(current.getPublicHost()).thenReturn("https://idp.example");
    backLink = new ProfileBackLink(sessions, clients, current);
    Mockito.when(sessions.participatingClients("cookie")).thenReturn(Set.of("spa"));
    Mockito.when(clients.loadPreautorized("acme", "spa")).thenReturn(Optional.of(client("spa",
        List.of("https://app.example/callback"), List.of("https://logout.example/bye"))));
    Mockito.when(clients.loadPreautorized("acme", "own"))
        .thenReturn(Optional.of(client("own", List.of("http://localhost:4200/*"), List.of())));
  }

  private static ClientDetails client(String id, List<String> redirects, List<String> logouts) {
    return ClientDetails.builder().clientId(id).allowedScopes(List.of("openid"))
        .allowedGrants(List.of("authorization_code")).allowedRedirectUris(redirects)
        .postLogoutRedirectUris(logouts).build();
  }

  private static SessionInfo session(String clientId) {
    return SessionInfo.builder().clientId(clientId).build();
  }

  private static String query(String url, String name) {
    String query = URI.create(url).getRawQuery();
    for (String pair : query.split("&")) {
      int eq = pair.indexOf('=');
      if (pair.substring(0, eq).equals(name)) {
        return URLDecoder.decode(pair.substring(eq + 1), StandardCharsets.UTF_8);
      }
    }
    return null;
  }

  @Test
  @DisplayName("A page of a registered origin of a client of the session is accepted")
  void accepts_registered_origin() {
    Assertions.assertEquals(Optional.of("https://app.example/orders?page=2"),
        backLink.accept("acme", "cookie", session(null), "https://app.example/orders?page=2"));
    Assertions.assertTrue(
        backLink.accept("acme", "cookie", session(null), "https://logout.example/").isPresent());
    Assertions.assertTrue(backLink
        .accept("acme", "cookie", session("own"), "http://localhost:4200/home").isPresent());
  }

  @Test
  @DisplayName("Another origin, scheme, port or a URL with userinfo is ignored")
  void rejects_other_origins() {
    SessionInfo session = session(null);
    Assertions.assertTrue(
        backLink.accept("acme", "cookie", session, "https://evil.example/orders").isEmpty());
    Assertions.assertTrue(
        backLink.accept("acme", "cookie", session, "http://app.example/orders").isEmpty());
    Assertions.assertTrue(
        backLink.accept("acme", "cookie", session, "https://app.example:8443/").isEmpty());
    Assertions
        .assertTrue(backLink.accept("acme", "cookie", session, "https://x@app.example/").isEmpty());
    Assertions
        .assertTrue(backLink.accept("acme", "cookie", session, "javascript:alert(1)").isEmpty());
    Assertions.assertTrue(backLink.accept("acme", "cookie", session, null).isEmpty());
    Assertions.assertTrue(
        backLink.accept("acme", "other", session, "https://app.example/orders").isEmpty());
  }

  @Test
  @DisplayName("The issuer goes in iss, keeping the query and before the fragment")
  void adds_issuer() {
    String link = backLink.withIssuer("acme", "https://app.example/orders?page=2&q=a%20b#top");

    Assertions.assertTrue(link.startsWith("https://app.example/orders?page=2&q=a%20b&iss="), link);
    Assertions.assertTrue(link.endsWith("#top"), link);
    Assertions.assertEquals(ISSUER, query(link, "iss"));
  }

  @Test
  @DisplayName("A URL without query gets iss as its first parameter, replacing an old one")
  void adds_issuer_without_query() {
    Assertions.assertEquals(ISSUER,
        query(backLink.withIssuer("acme", "https://app.example/"), "iss"));
    String link = backLink.withIssuer("acme", "https://app.example/?iss=old");
    Assertions.assertEquals(ISSUER, query(link, "iss"));
    Assertions.assertFalse(link.contains("old"), link);
  }
}
